local k={236,28,58,108,214,205,2,148,239,71,102,219,244,111,20,155,173,5,201,206,107,41,136,242,240,96,64,201,234,38,217,233}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
